summary={'Decision':'SECTION 6 READY TO LOCK — BOUNDED SEMANTIC VERIFICATION','Build':manifest['ImplementationBuildID'],'RegressionRun':'20260913T030324Z-075d96fc','ClosureRun':'20260913T030322Z-8f183b76','PreviousExecuted':770,'NewCases':98,'CurrentExecuted':868,'Pass':868,'Fail':0,'Unresolved':0,'NotRunInDeclaredExecutableDomain':0,'LegacyGapPlaceholdersStillStoredAsNotRun':5,'LegacyGapDisposition':gaps,'BoundaryCategories':2,'RegressionIDsAndExpectedOutcomesUnchanged':True,'OriginalEvidenceZIPStatus':archive_status,'Oracles':oracles,'NewCaseKinds':dict(collections.Counter(c['Kind'] for c in new)),'Statement':'No claim of exhaustive framework or complete implementation verification. Rows with several oracle tags overlap.'}
