table=['# Core closure: observed result tables','','Final build: UAIS-CORE-0.2.2. All reported outcomes are read from retained execution records. These tables cover a declared headless semantic model, not browser acquisition, rendering or empirical effectiveness.','','## Table 10. Revised coverage by oracle','','| Oracle | Planned executable | Executed | Pass | Fail | Unresolved | Not run in declared domain |','| --- | --- | --- | --- | --- | --- | --- |']
for r in oracles:table.append('| '+' | '.join(str(v) for v in r.values())+' |')
table+=['','Oracle rows overlap. Unique final instances: 868 = 770 unchanged regression cases + 98 additions. The five old not-run entries remain immutable historical gap placeholders; three are discharged by new evidence and two are explicitly outside the revised domain. They are not five remaining executable failures.','','## Table 11. Action-level semantic contract results','','| ActionID | Positive case | Transform or attempted unlisted transform | Checked postconditions | Invariants at configuration boundary | Observed property/effect | Result |','| --- | --- | --- | --- | --- | --- | --- |']
cat=json.loads((B/'specs/catalogue.json').read_text(encoding='utf-8'))['actions']
actionrows=[]
for a in cat:
 aid=a['contract']['ActionID'];cs=[c for c in new if c['Input'].get('action')==aid and c['Kind'] in ['effect','reject']];pos=next(c for c in cs if c['TestCaseID'].endswith('/positive'));other=[c for c in cs if c!=pos];out=pos['ObservedOutcome'];checks=pos['Details']['checks'];variants=[c['Input'].get('variant') or 'additional restore' for c in other]
 effect=out['property']+' = '+str(out['value'])
 if aid in ['R3.A1','R3.A2','R3.A6','R3.A7']:effect+='; separate '+pos['Details']['effect']['commands'][0]['command']+' admission/result'
 semantic_checks=[k for k in checks if k not in ['declared_property','mediated_coverage','trace_reconstruction','rule_source','command_phase_order']]
 row={'ActionID':aid,'PositiveCase':pos['TestCaseID'],'AdditionalCases':[c['TestCaseID'] for c in other],'PostconditionChecks':checks,'InvariantResult':pos['Details']['effect']['invariants'],'ObservedEffect':effect,'Status':'Pass' if all(c['Status']=='Pass' for c in cs) else 'Fail'};actionrows.append(row)
 table.append(f"| {aid} | positive: Pass | {', '.join(variants)}: Pass | {', '.join(semantic_checks)} | 5/5 true | {effect} | {row['Status']} |")
table+=['','Each positive record retains its scope, mediated need, RuleSource, property anchor, content/state witnesses, invariant vector and trace IDs. Transform checks retain purpose and justified scoped coverage; R2.A2 retains only the eligible optional scope and preserves the protected error route. Empty transformation lists are tested with an unlisted conversion and leave U/S unchanged. This is representative effect coverage, not exhaustive parameter/negative-branch coverage.','','## Table 12. Canonical key and deterministic resolver results','','| Test | Expected | Observed | Result |','| --- | --- | --- | --- |']
keys=[c for c in new if c['Kind'] in ['key','resolve','key-reject','dedup']]
for c in keys:table.append(f"| {c['TestCaseID']} | {c['ExpectedOutcome']} | {c['ObservedOutcome']} | {c['Status']} |")
table+=['','Pairwise key relations use −1, 0 and +1 for less than, equal and greater than. Binary-float/unknown/nonfinite decimal inputs are rejected as unavailable exact parameters. Equivalent canonical plans retain both provenance aliases and produce one selected semantic execution record through COMBINE; the representative alias is a record identifier, not an extra accessibility preference.','','## Table 13. Independently scoped multi-rule scenarios','','| Scenario | Concrete scoped support inputs | Nominated rules | Candidate actions | Compatibility/conflict and resolver outcome | Execution result |','| --- | --- | --- | --- | --- | --- |']
multi=[c for c in new if c['Kind'] in ['multi','multi_conflict']]
for c in multi:
 inp=c['Input'];out=c['ObservedOutcome'];components=inp['components'];scopes=', '.join(z['need']+'@'+z['scope'] for z in components) or 'No added support request/demand';acts=', '.join(z['action'] for z in components) or 'None; baseline safety retained';outcome=str(out.get('dispositions',{'selected':out.get('selected'),'operation':out.get('operation')}))
 table.append(f"| {c['TestCaseID']} | {scopes} | {', '.join(out['rules']) or 'Empty'} | {acts} | {inp['mode']}: {outcome} | {c['Status']}; semantic state preserved |")
table+=['','The term request justifies N1→R1 with its N1→R2 condition false. Independent N4 reminder scopes justify R2 through retained grouping references, R3 through interrupted draft-reference continuity, or R4 through staged references with preserved back/review access. Each conditional edge has separate frozen object-level facts. Their unions generate all sixteen subsets, so no requested subset was unreachable in this fixture. The two competing-plan scenarios use a controlled exclusive-support-region feasibility witness; they do not assert that all action pairs inherently conflict. The complete context/condition/edge records are in the JSON inventory and traces.','','## Table 14. Regression and acceptance history','','| Package/check | Executed | Pass | Fail | Notes |','| --- | --- | --- | --- | --- |','| Prior selected baseline | 770 | 770 | 0 | Preserved, not replaced |','| Final regression of same IDs/oracles | 770 | 770 | 0 | No old executable case disappeared |','| Final closure additions | 98 | 98 | 0 | 49 action/transform checks; 27 canonical checks; 21 multi-rule cases; one query provenance check |','| Final unique executable inventory | 868 | 868 | 0 | Zero unresolved and zero not-run executable cases inside declared domain |','| Initial stricter trace acceptance | 8 | 0 | 8 | Retained earlier failures |','| Intermediate transaction acceptance | 5 | 0 | 5 | Retained earlier failures |','| Equivalent-plan audit on 0.2.0 | 2 | 0 | 2 | IMPL-003, retained |','| Equivalent-plan retest | 2 | 2 | 0 | Included in 98, not added again |','| Final independent trace acceptance | 8 | 8 | 0 | Separate audit of representative regression traces |','| Final transaction acceptance | 5 | 5 | 0 | Same TX-1 criteria |','| Final trace-checker negative controls | 3 | 3 | 0 | Missing version/token/parent rejected |']
